const { name, email, phone, service, date, time, notes } = $input.first().json.body;
if (!name || !email || !date || !time || !service) {
  throw new Error('Missing required fields: name, email, date, time, service');
}

const OFF = '-04:00';
const startISO = `${date}T${time}:00${OFF}`;
const endISO = new Date(new Date(startISO).getTime() + 1800000).toISOString();

const d = new Date(startISO);
const displayDate = d.toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric', timeZone:'America/New_York' });
const displayTime = d.toLocaleTimeString('en-US', { hour:'numeric', minute:'2-digit', timeZone:'America/New_York' });

return [{ json: {
  name, email,
  phone: phone || 'N/A',
  service,
  notes: notes || 'None',
  startISO, endISO,
  summary: `Appt: ${service} — ${name}`,
  description: `Phone: ${phone || 'N/A'}\nEmail: ${email}\nService: ${service}\nNotes: ${notes || 'None'}`,
  displayDate, displayTime
} }];
